use std::collections::HashMap;

pub const OPERATION_FIELD: &str = "operation";
pub const COVERAGE_REQUIREMENT_FIELD: &str = "coverageRequirement";
pub const SUBMIT_OPERATION: &str = "submit-audit-unit";
pub const REQUIRED_COVERAGE: &str = "required";

pub struct SubmissionResult {
    pub accepted: bool,
}

