import { randomUUID } from "node:crypto";

export function routeUrls(): readonly string[] {
  const optionalComponents = ["", randomUUID().replaceAll("-", "")];
  const urls: string[] = [];
  for (const query of optionalComponents) {
    for (const fragment of optionalComponents) {
      const url = new URL(`https://${randomUUID()}.invalid/${randomUUID()}`);
      url.search = query;
      url.hash = fragment;
      urls.push(url.toString());
    }
  }
  return urls;
}

