export function routePath(routeUrl: string): string {
  const authorityStart = routeUrl.indexOf("://") + 3;
  const pathStart = routeUrl.indexOf("/", authorityStart);
  let pathEnd = routeUrl.length;
  for (const separator of ["?", "#"]) {
    const separatorIndex = routeUrl.indexOf(separator, pathStart);
    if (separatorIndex >= 0) {
      pathEnd = Math.min(pathEnd, separatorIndex);
    }
  }
  return routeUrl.slice(pathStart, pathEnd);
}

